import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"易雅","description":"周易輯聞 - 易雅","frontmatter":{"title":"易雅","description":"周易輯聞 - 易雅"},"headers":[],"relativePath":"classics/jiwen/009.md","filePath":"classics/jiwen/009.md"}'),r={name:"classics/jiwen/009.md"};function i(n,p,c,_,o,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="易雅" tabindex="-1">易雅 <a class="header-anchor" href="#易雅" aria-label="Permalink to “易雅”">​</a></h1><p>欽定四庫全書</p><p>宋趙汝梅撰通釋第一</p><p>昔者聖人之作易也，將以明道也。道無形，曷從而明之？唯寓之象數而已。象數非所以為易，非象數則無以見易。易不可見，則道何由而明哉？是故求道者必於易，求易者必於象數。象數之於易，猶木之本、水之源也。「一陰一陽之謂道」，奇耦其寓也。像之為象，陽奇而陰耦；數之為數，陽一而陰二。過此以往，則有辭焉。辭也者，聖人所以發象數之縕，而明此道也。夫易之卦有體焉，有名焉。體以數成，名以象得。易之爻有位焉，有吉凶焉。位以數列，吉凶以象顯。何謂體？儀象遞生，八卦成列，因而重之，六畫成卦，豈非以數成體乎？何謂名？乾坤是也。積六陽有天之象，天行健，故曰「乾」。積六陰有地之象，地勢順，故曰坤。豈非以象得名乎？何謂位？初、三、五為陽，二、四、上為陰。六爻既備，六位成章，豈非以數列位乎？何謂吉凶？潛龍安於下則宜，履霜至於冰則殃。豕一也，吉於豶牙，兇於蹢躅。車一也，積載於二，曳輪於初。豈非以象顯吉凶乎？卦有六十四，一卦一名，一名一時。爻有三百八十四，一爻一位，一位一變。彖辭統一時之義以斷其情，爻辭辨六位之情以盡其變。釋彖所以明卦下之辭，錯綜其辭所以極卦爻之變。小象以明諸爻，大象以明兩體。使世無古今，人皆聖知，則道不待傳，言且可廢，又奚象數辭義之足雲？包犧御上古真樸未漓之時，已不能不見之畫，況當中古憂患之日，聖人能坐眂生人之顛越，而獨吝於言乎？故辭所以明象數，象數所以形道。道固非囿於象數之中，象數則未嘗出於道之外。是故求象數者必本於道，求辭者必本於象數。謂得道而象數在其中則可，必欲遺象數而求道則遠矣。是故象數者，餘之所謂水之源，木之本也。卦有定名，猶水之濫觴，木之芽甲，定為某水某木也。六爻則流派枝葉也。流派有通塞，枝葉有華瘁，則諸爻之吉凶也。辭則水之經，木之譜也。學者觀水經木譜而不尋其源，察其本，故不及者因習而訛經譜，過之者牽合經譜以證己說，此易道所以不明也。易道貫通萬古之變，易書該括萬變之情。玩畫而不探得名之原，是謂不知卦。玩辭而不循名卦之義，是謂不知言。不知卦，不知言，而謂之知易，吾未之信也。知卦矣，知言矣，然後以卦為吾所遇之時，以爻為吾所居之位，以爻象為吾所為之事，深思而詳處之，然後玩辭之吉凶，以驗己之所行，則一卦一爻一辭，皆吾受用。大君之宰制宇內，大人之參贊化育，達而尊主庇民，窮而儉德遁世，無入而不自得。此聖人觀象玩辭之學，洗心憂世之方也。籲！言象數於今之世者，亦難矣，漢儒累之也。漢儒累之，故虛無者得以荒之，浮辯者得以亂之，占驗者得以訛之。餘今所云者，聖人之象數，非漢儒之象數也。以之進德修業，以之傳道解惑，庶或取諸。書釋第二。</p><p>易獨得全，非幸也。非幸者何？聖人所嘗憂也。聖人樂天知命，夫奚憂？由其與民同患。故聖人之憂天下，甚於天下之自憂，而易所以作也。易為憂世而作，詎肯自置於不自憂之域？則掌於大卜者，聖人自憂之深也。是以苛法之禁，虐焰之毀，凡足以經理天地、綱紀王國之書，皆燼滅而灰絕，唯易得免焉。夫易之存，聖人非有扼制之術，甘誘之具也。聖賢達觀夫吉凶之理，則安行於易。凡人謬迷於利害之中，則不知有易。唯暴強無良之人，棄滅仁義，殘刻禍賊，外若無所忌憚，然其降衷以生，疑成慮敗，趨吉避凶，均有是心，倚易為命，期自發乎怵惕之場，意秦皇之私，必有甚於眾人，則秦之存易，直以自存，聖人雖憂之，若弗與焉。嗚呼！周興而易以興，周亡而易不亡，則夫卜世卜年，聖人豈徒欲知其享國之數而已？不然，蓍以靈艾，龜以靈刳，聖人豈若敗株枯介之不自靈邪？故曰：易獨得全，非幸也。漢興，群經殘闕，或曰傳於老生，或出自屋壁。諸儒專門世守，鵠首窮研，雖斷編遺簡，猶將曲通其義。唯易為全書，探討最易，孰謂其紛揉反甚於他經？劉向以中古文易經校施、孟、梁丘經，或脫去「無咎」、「悔亡」，獨費氏經與古文同。施、梁丘、高氏亡於西晉，孟、京亦不傳。陳元、鄭眾皆傳費學，馬融、鄭玄、荀爽、王肅、王弼皆為之注。今易乃費氏經也。馬、鄭諸書已不全見，今孤行者，王弼本爾。唐郭京作舉正，自以為得王弼、韓康伯手寫註定傳授真本，於今易有所損益，凡一百三條。坤初六象曰：</p><p>「履霜堅冰，陰始凝也。」京本無「堅冰」二字。案：此乃舉爻辭以通釋文義，謂言履霜而遽及冰者，霜為陰凝之始，冰為陰凝之極，故言始凝以明堅冰之漸。儻去「堅冰」，但云「始凝」，則「始」字無因而發。或者京因魏許芝之對而云爾。卜史一時之言，可據以改經邪？比六五象曰：「舍逆取順，失前禽也。」京本「失前禽」在「舍逆取順」之上，意彼以釋辭在上，爻辭在下，乃倒顛之。案：小象類此頗多。恆九四曰：「田無禽。」象曰：</p><p>「久非其位，安得禽也。」解初六曰：「無咎。」象曰：</p><p>「剛柔之際，義無咎也。」旅九三曰：「喪其僮僕。」象曰：「以旅與下，其義喪也。」凡是與比正同。此聖人互文明理之妙，庸可臆改？夫易，全書也，後人猶挾王、韓之名以更古文，他經何望焉？況自保氏失官，書不同文，漢、魏以來，家自為書，書自為說，固有一字而數音，一音而數字，數義而一字，數字而一義者。學者求之今易而不通，乃參以他本，甚至或改或損益，如郭京輩，使學者無所取裁。其用心字學者，則斷以許氏說文，不知先秦文簡，每多假借，不特易經為然。彼說文作於東都，至魏、晉間，世人未之程式，如大過「枯楊生稊」之類，考之字書，曾靡有定，烏可執以為據？唯求音義於經旨，則可信矣。餘既幸易為全書，故粗論字義之誤於此。學釋第三。</p><p>書所以載道，易所以名書也。包犧闡道而寓之畫，畫則書之權輿也。三代皆有書，夏首艮，曰連山；商首坤，曰歸藏；周首乾，曰周易。今之易，周易也，文王愛世之所演也。上篇始乾、坤，天地之體也；終坎、離，天地之用也。下篇始鹹、恆，人事之體也；終既、未，人事之用也。是乃三極之道也。周公系爻，倚物象以明理。物象者，畫之證者也。夫子系傳，本之以性命道德，居則觀象玩辭，動則觀變玩佔，盛德大業，由此乎出，於是文王、周公之旨大明矣。自秦垢莫汙，其書傳授歷歷可考。傳言商瞿受易於聖人，歷橋庇、馯臂、周醜、孫虞、田何，不聞有所述作。何傳王同、周玉孫、丁寬、服生，皆著易傳。丁將軍學最盛，有施、孟、梁丘三家。又費直以彖、象、繫辭解說上下經，高相亦傳丁將軍學，然其書皆亡。所可考者，梁丘賀以占筮顯名。漢宣時，費直長於卦筮，高相專說災異。其後虞翻、關子明之徒，尤注意於佔。至管輅雖分筮、卜、卦，乃絕口不及易中辭義矣。嗟夫！夫子系易之書，幸傳於漢世，而諸人大率皆主於筮卦災異，而反遺性命道德，何邪？商瞿在孔門非名弟子，意者止受占筮於夫子，故其所傳僅如是邪？太史公自序謂受易於楊何，乃止雲「易著天地、陰陽、四時、五行」，則自商瞿以來所傳，益可見矣。易專為筮，未經吾夫子之手之說也。言災異，則筮卜之遺意也。若焦延壽不祖田陽，不用筮卜，自成一家。京房傳之，專明卦氣占驗。極而至於蘇竟、郎顗、楊由、景鸞、樊英之徒，則以易兼河洛、圖緯、風角、七政，而易儕於讖緯矣。西漢之末，向長、範升諸人好談老、易，東都則折像，魏則何晏、王弼、崔徽皆以玄說易，後至杜弼、王希夷、王績、武攸緒輩皆好之。唐開元初，詔張說舉通易、老、莊者，則易又儕於老、莊矣。孫盛論王弼曰：「敘浮義則麗詞溢目，造陰陽則妙賾無問，至於六爻變化，群象所效，日時歲月，五氣相推，弼皆擯落，多所不關。玩辭、玩佔，二者可偏廢乎？」隋世弼注盛行，諸家微絕，孔穎達為弼作疏，自是流入文辭，不唯舉觀變玩佔之事，鄙之為星翁卜祝之學，且並聖人觀象之妙理而棄之。夫易，畫備於包犧，辭詳於三聖，性命道德之縕，夫子畫以發之。顧乃災異於西漢，圖緯於東都，老莊於漢魏之交。隋絕圖緯，唐祖玄元，故老、易獨行，學者瀾倒。籲！可嘆已！賴我朝王昭素、胡安定諸儒挽而回之，伊洛益閎其說，究極指歸，然後始復為性命道德之書，後學何其幸邪！然猶有旁支疑似易以惑人者。互體非象也，而或取以釋象；圖緯、老、莊非辭也，而或取以釋辭；遊魂、歸魂非變也，五行、納甲非佔也，而或取以用之變佔。何異端而多岐邪？然易固無恙也。若揚子云擬易以作太玄，而主於歷；魏伯陽假爻象以作參同契，而主於養生。他如洞極元包，皆依彷占筮而作，下焉越方，考鬼家亦竊取之，又何害於易哉？易家有子夏傳，儒先多引以斷疑，雖於其書，不於其人，然亦不容不辨。蓋由隋志以為卜商故，後人承而弗察，信之者以為京房為之箋，疑之者以為近世人以王弼本冒為之傳。世有兩書，今觀諸儒所引二書中語，皆不類洙泗氣象，縱微後人冒作，亦決非卜商之書。孫坦氏曰：「世有子夏傳，以為親得孔子之縕。觀其辭，間或取左氏春秋傳語證之。晚又得十八佔，稱天子則曰縣官。」嘗疑漢杜子夏之學，竊以為卜商但嘗言詩，未聞明易。案：欽鄴與鄧彭祖、王商、萬章、禽慶之徒，皆字子夏，二杜於易未聞師授，孫氏之論尚為可疑。唯彭祖傳梁丘之學，如以子夏為彭祖，猶有彷彿，以為欽鄴則無所依據。餘未敢以隋史為信，世之說經者，更詳之。情釋第四</p><p>吉凶悔吝生乎動。動者何？情也。情者何？性之動也。一氣判而陰陽分，鍾之為物，得陽者剛，得陰者柔。人生而靜，天之性也。靜故不動，不動則吉凶悔吝之故泯矣。靜不能無動，故發而為善惡、邪正、愛惡、暌合之情。情動於中，物應於外，以是則吉，以是則兇，以是而悔吝。苟能知幾先見，有吉而已，否則反是。聖人慮後世溺於情而不自制，故設卦而類萬物之情，以盡其情偽，以示後世。且經卦既重，雖純乾猶貴於利正，以其不免於動也。利正者，性情也。況八卦相蕩而情已交，則一卦自有一卦之情。六爻發揮，雖純乾猶事於旁通，亦以其不能免乎動也。旁通者，通其情也。況剛柔相推而情愈繁，則一爻自有一爻之情。卦之情顯於名，爻之情象於物。乾、坤之合，乾下為泰，上為否。震、坎之合，震下為屯，上為解。合卦一而義胥反者，情不同也。剛居三，在乾則厲，在謙則吉。柔居四，在小畜為畜德，在剝為剝膚。剛柔一而事胥反者，情不同也。情之不同如是，豈紛散無所統一者？五為君位，端拱於上，其經綸宰攝，乃屬之臣。彼爻畫變動，周流六虛，或屈伸內外，或得失當否，其為某卦某時，則自有主時之爻。故諸爻鄉背，其情悉繫於此爻。然後六位旁通，脈絡綜貫，六爻交胥為用，固自秩然不紊。是故卦之時，爻之位，皆因情以成吉凶。三聖人之辭，皆因情以明吉凶。故曰：「八卦以象告，爻彖以情言。剛柔雜居，而吉凶可見矣。變動以利言，吉凶以情遷。是故愛惡相攻而吉凶生，遠近相取而悔吝生，情偽相感而利害生。凡易之情，近而不相得則兇。或害之，悔且吝。」又曰：「聖人之情見乎辭。」學者當玩聖人之辭，以求卦爻之情，即卦爻之情，以制己之情，庶幾情復於性。此聖人繫辭之情也。位釋第五易闡於三畫，而三才之象顯。卦重於六畫，而三才之位備。位也者，所以列貴賤，明外內，虛之以待剛柔之迭居，辨之以定趣變之吉凶者也。夫兩儀形太極之判，四象為兩儀之衍。合兩儀、四象而象三才，故上為天，中為人，下為地。天、人地三才顯矣，而位猶未備，兼而兩之，故六位而成章。上五為天，四三為人，二初為地。天天，人人，地地。 大畜上九：「何天之衢，亨。」乾九五：「飛龍在天。」九四、九三，上不在天，下不在田。九二：「見龍在田。」初九潛龍勿用。 三才之道如是。析而六之，則六位各有所配。以類人事，則五為君之正位，又為陽之正位；二為臣之正位，又為陰之正位。陰□陰，陽□陽。 需位乎天位，以中正也。蹇六二：「王臣蹇蹇。」 四為近臣，三為公，初上為外諸侯□○□公○□。 泰上六：「開國承家。」豫九四：「由豫大有得。」大有</p><p>九三：「公用亨於天子。」屯初九：利建侯。 上又為高尚之臣，初又為民及未仕之賢□○○○○□。 蠱上九：「不事王侯。」姤九四：「遠民也。」民指初六。乾初九：潛龍。 析上下卦而論，則上為天，下為地。天天天，地地地。 否天地不交， 初為內，三為外、為終○○□○○內。</p><p>無妄「剛自外來而為主於內」，謂剛自二來初。乾九三「知終終之」。 二五為中，為內。○□○○□○ 「大有大中而上下應之」，指五。「蒙時中也」，指二。比六二「比之自內」。指二五。 合六爻而論，五、四、三二為中，初、上為外，為初終，為上下，□中中中中□ 子曰則非中爻不備。指五、四、三二。需初九「需於郊」。同人上九「同人於郊」。師初六「師出以律」。以出為初。否上九「否終則傾」。乾初九潛龍勿用，下也。井上六「元吉」。在上 四為互純爻之中，陰陰中，陰陰陽。 復六四「中行獨復」。 由下而上為往，由內而外亦為往。□□□□□□， 泰，「小往大來」，為由下而上。屯六四「往吉」。由四往初，為由內而外。 由上而下為來，由外而內亦為來，由主視客亦為來。□□□□□□， 復「七日來複」，為由上而下。</p><p>無妄剛自外來而為主於內，為由外而內。需「三人來」，上為主，三人為客。 其為是參錯不一者，所以極六位之變，此爻位之別也。剛居陽，柔居陰，為當位，反是為不當位。柔剛柔剛柔剛。</p><p>既濟，「剛柔正而位當」。未濟：踓不當位。 剛自陰之陽，柔自陽之陰，為得位，反是為失位。○○□○○○ 漸六四「進得位」，小過九四「剛失位而不中」， 剛柔合為應。剛柔剛柔剛柔 未濟「剛柔應也」。 純為敵應。剛柔柔剛柔柔。 艮上下敵應， 上臨下為乘，下奉上為承。○○□○□□ 七「乘馬班如」。謂乘初。六四「乘馬班如」。謂應初而乘之。蠱初六意丞考也。謂承五。 是故互則大明中天，臨制萬國。如「飛龍在天」，「火在天上」之類是也。二則得時行志，尊主庇民。如「在師中吉」，「包荒得尚於中行」之類是也。三四居危疑之地，故多虞於兇懼。初上為始終之際，故罕系乎吉凶。此居位之常也。然諸爻有當位而反疑，不當位而反利者。賁為剛柔交賁之時，四乃舍三而賁初，則九三、六四雖當位而反疑。噬嗑用獄之象，柔上進而得中，則六五雖不當位而反利。此居位之變也。九四之「萃群陰」，既「大吉」矣，以其近君而擅民，聖人必嚴不當之戒。九三之「勞謙」，屈天道矣，以其有功而不德，聖人乃明有終之吉。此又吉凶無常，唯時是適，斯易所以能周萬變而不窮者歟？王氏略例曰：乾上九文言云「貴而無位」，需上六雲「雖不當位」。若以上為陰位邪，則需上六不得雲「不當也」。若以上為陽位邪，則乾上九不得雲「貴而無位」也。陰陽處之，皆雲非位，然則初上者，是事之終始，無陰陽定位也。籲！殆未足以論位之變也。聖人言位，有指本爻者，有指他爻者，有析六爻者，有總三爻者。萃九五曰「萃有位」，謂九四已「萃群陰，九五僅有位而無民」。此指本爻之位。乾上九曰「貴而無位」，謂上九居飛龍之上，無財成輔相之位。此指他爻之位。既濟曰「剛柔正而位當」。謂六位之陰陽皆當。此析六爻之位。需上六曰：「雖不當位。」謂上三爻為天陽之象，於陰為不當。此總三爻之位。爻位之變不同，故爻位之辭亦不同。儻拘於析位之陰陽，而遂謂初、上無陰陽定位，則蒙九二、晉六三、豫九四、大有六五，不聞以不當位為嫌，是中爻亦無定位，庸止於初、上乎？略例謂之「無定位」，而需爻直注云「無位」，益舛矣。雖然，此聖人吉凶與民同患之故爾。至於範圍輔相，所貴又不止此。剛居二而帥師，猶有毒天下之憂；至五則比輔而下順從矣。柔居二而同人，則有伏戎乘墉之吝；至五則大中，而上下應矣。此由居五而有功者也。「豫」之世，臣強君弱，而得常不死者，幸居中而未亡。需之時，陽礙於險，其得不困窮者，以有九五天位之君。此由居五而免咎者也。然則聖人之大寶曰位，詎非五乎？象辭變佔總釋易者，道德性命之書也。三易掌於大卜，易固專於佔也。聖人為之辭曰：「君子居則觀其象而玩其辭，動則觀其變而玩其佔。」易豈專於佔也哉？觀於卦，餘知象之所存乎；玩其象，餘知辭之所由發也。觀其蓍，餘知變之所存乎；玩其變，餘知佔之所由立也。是故求佔者，必於變，求辭者，必於象。或曰：「得象可以忘言，知變則又奚假於佔？」然而必貴乎是者，變佔以前民用，象辭以同民患，皆道德性命之故也。餘懼或者偏倚於一，故揭聖人之言，析而明之。象釋第六</p><p>太極混融，道函三才之象。太極既判，道寓三才之中。是以三才有象，而至道無形。夫天運於上，日月麗焉。地載於下，山川出焉。人物生其間，動植分焉，莫非象也。然則要其所以為象者，非道而何？故道雖無形，而見象即可以見道。凡至神至賾之理，皆寓於可指可索之象。象即理，理即象也。夫理寓於三才，在在昭露，聖人通之，凡人迷之。聖人慾天下後世洞明無形之道，故即有形之象而示之。且設卦之初，將以周萬變而盡情偽，似若疲精竭神，窮搜而冥討者。然跡其仰觀俯察，近取遠取，曾不過天地人物之象，未嘗為希夷奇秘之說，以驚世衒俗，使人不可思而得，學而至也。然象至顯也，亦至微也。自夫人求理於深僻，遂目象為淺鄙，由其淺鄙視物象，而象之理遂不暇明。象之理不明，而曰知易，未之或知也。是故聖人有以見天下之賾，而擬諸其形容，象其物宜。包犧觀象而作卦，文王、周公因象而繫辭，故曰：「易者，象也。」純陽象天，象不止天而剛健之理可求；純陰象地，象不止地而柔順之理可得。震巽以動，巽之理象風雷，艮兌以止說之理象山澤，坎離以虛明流行之理象水火互乘而六十四卦變動，而三百八十四爻。物物有象，象象具理，觸類而格之，象不可勝窮，理不可勝用，則精粗一貫，窮達一致。其曰「自天祐之，吉無不利」，非誣我也。聖人謂言不盡意，故立象以盡意，則象非可鹵莽而定也。物理精微，格知其極，然後可得而定也。乾坤陰陽，敻殊也，而坤上稱龍。戶庭門庭，幾近也，而吉凶胥反。履之虎不咥於卦而咥於爻。小畜之雲雨於爻而不雨於卦言桎梏，於蒙之初而言校，於噬嗑之上下言鴻，於漸之六爻而言飛鳥，於小過之初上，蹇之五二不稱往來。中孚諸爻象皆不類。木取枯楊，金別黃金，水指井谷，火極焚巢。聖人沿理以象物，其精微若是，雖疑似之間，斷乎其不可易。奈何漢儒習聞春秋以來筮易之辭，不察聖人象物之意，於是以象為象，不以象為理；玩辭以辭，不玩辭以象。甚而取筮家玄體與術家卦氣五行諸說而附益之，其淫流蔓茹，罔知紀極。王輔嗣病其然，則為「得意忘象，得象忘言」之論以通之。其說曰：「義苟合順，何必坤乃為牛？義苟應健，何必乾乃為馬？」然質諸聖人之言，馬乃一畫剛之象，健則三畫乾之德，在需乾居坎下，以剛健而免險陷之災，至重坎雖各具一陽，而六爻終無出險之象。儻指一畫之剛為三畫之健，不亦違聖人之情，而謬失得之幾乎？聖人因卦爻而立物象，卦爻所無，聖人不輕象以物也。輔嗣尤漢儒之案文責卦，乃欲忘象以求義。且聖人設卦觀象，舍象無所觀也。象既忘矣，何義之可求？使義可忘象而得，則聖人何為立象以盡意？是漢儒病於固滯，輔嗣則流於荒忽矣。夫三才有是理，則包犧有是象；卦爻有是象，則文王、周公有是辭。夫子所謂剛柔當否之類，蓋指觀象之法，以探三才之理。然則辭也，象也，理也，一物而異名者也。至若說卦之象，與諸卦之象不同，乾卦不言馬，而說卦為馬；震卦不言龍，而說卦為龍；大畜稱牛豕，說卦乾、艮不為牛豕；大過稱茅、楊，說卦巽、兌不為茅、楊；至為布、「為大塗」、「為心痛」，為蚌等，皆諸卦所無。若以左傳筮易之象參之，疑說卦後章為佔家玩佔之象，後人或取以附夫子說卦之末，猶諸緯皆稱夫子之筆是也。況此文失於漢初，至孝宣時，河內女子發老屋得之。又荀、鄭、馬、虞諸家之象，多寡不同，以故不能不起後世之疑。唯得象之理者，可以無惑。辭釋第七</p><p>天何言哉！言不盡意，而猶曰「繫辭焉以盡其言」，辭殆不可已也。辭詔於當時，書傳於萬世，聖人非浮於辭，聖人之情見乎辭者也。子曰：「易之興也，其當殷之末世，周之盛德邪？當文王與紂之事邪？是故其辭危。危者使平，易者使傾，此又易之道也。」時有憂樂，故聖人之辭亦有憂樂。時樂時憂，聖人何容心哉！得時則樂，得位當位則樂，有應有比則樂，樂之中有戒焉，有懼焉。不得時則憂，失位不當位則憂，無應無比則憂，憂之中有慎焉，有幸焉。樂之辭暢以約，戒之辭法，懼之辭嚴，憂之辭懼以微，謹之辭危，幸之辭寬。連山、歸藏已亡，其辭莫考。若周易，則文王之彖，周公之爻，皆以發其憂樂之情。乾「元亨利貞」，樂辭也。豐亨則示日中之戒。臨「元亨」而猶懼八月之兇。剝「不利有攸往」，憂辭也。明夷則艱貞以致謹，遁則猶幸利貞而致亨。隨「孚於嘉吉」，樂也。泰三戒於「勿恤其孚」，鼎四懼於「折足覆餗」，師「或輿尸」，憂也。遁初謹於「勿往」，豫五幸於「不死」。凡此皆事明而辭顯。至於變動不居，憂樂迭見，其微辭奧義，皆可涉涯涘而窺浩渺。坤之五欲顯，然辭之曰「君」，而卦為純陰，其言「黃裳」者，取居中處下之義，示坤之當下於乾，隱然有後妃之象。他如泰之「歸妺」，剝之「宮人」，明夷之「箕子」，皆有深意，以垂萬世之訓。玩文、周之辭，至此無餘縕矣。奈何聖哲少而中才多，故吾夫子為之辭，或發凡，或辨疑，或足其微旨。如天、地、風、雷、水、火、山、澤，以擬其象，健、順、動、巽、明、險、止、說，以體其德性，失得以紀變，當否以辨爻，中正以立本，乘承、應，此以明位。立卦而觀，則為上下、首足、本末、升降。偃卦而觀，則為內外、前後、往來、始終、消長。若是皆發凡之類。無咎一也，有誰咎，有不可咎，當位吉也，有當位而疑，有不當位而利。若是皆辨疑之類。萃九四「無咎」，而尚嚴位不當之戒。離六五「出涕戚嗟」，而特尊為王公之離。若是皆足其微旨之類。若夫辭嚴義明，以片言別知蒙而不失之略。 蒙曰「險而止蒙」，蹇曰「見險而能止，知矣哉」，只益一能字而知蒙分 辭眾理備句為之釋，而不失於詳。 此五六爻 義有錯綜，如歸妹，則上下文不嫌於異。 上言「天地之大義」，下言「天地不交」，文似背馳， 理不可易。如震，則彖、象辭不嫌於同。 釋彖、釋初九爻， 若此者非一，所當深玩而密求之也。嗟夫！三聖人之辭，或因畫之象，或因象之義，皆有攸本。畫之象，有通一卦為象者，有析上下卦為象者，有指一爻為象者，有合數爻為象者。象之義，有通一卦起義者，有析上下卦起義者，有指一爻起義者，有合數爻起義者。各釋之本文，難以枚舉。大抵有畫即有象，有象即有義。曰象曰義，名雖不同，其為繫辭之本一也。子曰：「將叛者其辭慚，中心疑者其辭枝。吉人之辭寡，躁人之辭多。誣善之人其辭遊，失其守者其辭屈。」此又聖人以易觀人之要。玩易君子，當更求其所以為辭。變釋第八</p><p>至哉變乎！知變化之道者，其知神之所為乎？無形者不變，有形而後變。厥初何形？亙萬古而長存。洎陰陽判而變以生。在天則四時變通，在地則變盈流謙，人物則遊魂為變。舉天地人物，皆囿於變而不自已，而神則妙乎其中。變也者，其生生不熄之理歟？是以聖人化而裁之，裁此變也；神而明之，明此變也。據會要，觀方來，使天下之人趣時不倦，既成萬物，而參贊化育矣。聖人知變，凡人昩變。彼禍福之倚伏，吉凶之胥禪，成矣而敗忽繼焉，是矣，而非或胎焉。況時有汙隆，政有損益，蓋將日異而月不同，推而百千萬年之後，其變有不勝紀者。於是聖人作易畫卦，剛柔相推，以盡天下之變。揲蓍求卦，爻象變動，以逆天下之變，而天下之能事畢矣。且自蓍而言，自分二掛一，至三變而一爻成，十有八變而六爻備。此蓍變而成爻者也。六爻成矣，爻之中凡得七八者不變，九變陰，六變陽，一卦之變六十四，通為四千九十六卦，此因爻而變卦者也。方未分蓍之初，陰陽之爻猶未別，至分二而始寓於兩握之中。雖寓也，而猶未見，至三變而後見。既見矣，卦未備也，十有八變而後備。既備矣，卦遇九六者，至互變而後定，而吉凶可得而佔焉。嗟夫！揲蓍之法，聖人幽贊於神明而生之者也。然聖人能立法以盡變，而不能逆知其變，當分二之後，未揲之前，莫辨爻之為陽為陰，雖至十有七變，猶未別為何卦，是以其變不測，而蓍之神為無窮，然非荒誕茫昩，無有條理也。詳玩靜索，實由自然，故分掛揲歸，若參錯不齊，而初變不五則九，次變三變不四則八，未始少紊。三變之餘，為九者十二，為七者二十，為六者四，為八者二十八，其多寡敻絕如是。而類之為陰陽各三十二，總之為六十四，正與卦數等。於至變之中，有不變者存。以其不變，此至變之所由出也，是謂變卦。復自卦而言，其變凡二：有卦變，有爻變。經卦互重以成六十四卦之體，此卦變也。爻重為六，因各有變，自卦下陰陽之純者為始，上下互易而極三百八十四爻之變，此爻變也。乾坤重卦交而為六，䷫䷗為一陰一陽之始，凡爻之一陽五陰與一陰五陽者，皆由此次第互易而變。各五卦。䷠䷒為二陰二陽之始，變如上，各十四卦。䷊䷋為三陽三陰之始，變如初，各九卦。卦變之辭如「健而巽，止而說」；爻變之辭如「剛來而下柔，柔進而上行」，皆聖人作易之所取也。六卦之變，先後有序，秩然一定，儻一循其變而索之，聖人釋彖之意，昭然義見矣。或曰：六十四卦自八卦而變，今震坎艮皆自臨變，巽離兌皆自遁變，豈先有臨遁，而後有六子邪？曰：合經卦重卦而論，則三重為六，是八卦為先，六十四卦為後。但指六畫而論，則八卦互重，一時同變，豈復有先後之分？聖人於噬嗑曰「頤中有物曰噬嗑」，非先有頤而後有噬嗑也。況卦變、爻變，例各不同，烏可比而壹之邪？或曰：包犧畫卦，目擊道存，卦變之外，復有爻變，回視包犧之畫，何繁簡若是？曰：包犧雖未命辭，而憂世之根柢已寓於畫。文王、周公因卦爻之變而辭之，良由萬古之變無窮，而易之變包乎萬變之表。雖中古所無，後世未有之事，而易中已先具其理。卦變之外，復有爻變，乃自然之故，聖人詎容特秘之？故世有此事，而易無此變，則非所以為易。易有此變，而不能明此變，則不足與言易，非聖人之不憚煩也。聖人因變而命辭，若文王釋卦、周公釋爻是也。至夫子則兼卦與爻，極其變以錯綜之，文王、周公之辭可知已。夫子兼極卦爻之變，請舉隅以明之。訟之辭曰「上剛下險」者，釋乾上坎下之體也。曰「剛來而得中」者，訟二陰爻，卦自䷠變九三來為九二而得中，䷅此釋二三兩爻之變，他卦皆然，特辭有顯晦，未易卦為之釋爾。無妄之辭曰：「剛自外來，而為主於內」，此析經卦而論，三為外，初為內。蓋無妄初爻之陽，自䷠下卦九三變來，初䷘而為主於內。凡是通謂卦變。若夫復即是剝，夬即是姤，以至三陰三陽之卦，特在反覆升降之間爾，實一理也。其他如李之才相生圖，邵康節反對升降之說，義皆幾近。若朱漢上所載虞仲翔卦變，則錯雜而無統。左傳蔡墨所舉，止為一爻變之例，一世二世之變，流於術矣。衛元嵩取之為元包，又其末也。焦延壽所變，雖與蓍合，其辭不經，要非聖人之意。第細玩三聖人之辭，皆有自來，觸類而長，其變不可勝窮，豈止三百八十四而已乎？又豈止四千九十六而已乎？其他象位之變，各具本篇。佔釋第九</p><p>心扃虛靈，物來先覺，佔何為者哉？自利慾熾，良性不君，乃有溷吾清明者。故辨妍醜不若鏡，別輕重不若權。且昭然一定者猶爾，況是非兇吉，伏於幾先，其趣舍殊軌，欲決疑似而斷群惑，烏得不託諸物之靈？夫蓍，物之無心而靈者也。聖人神明其德，心洞隱賾，固不假蓍。自夫吉凶與民同患，以易洗心，於是取物之靈者，立為佔法。非其避就惑亂於胸中，特借是以斷天下之疑爾。舜之禪禹也，「朕志先定，詢謀僉同」，而後問之龜筮。成王之黜殷也，民獻有十夫，予翼以於敉寧武圖功，而後恊之夢卜。是禹可禪，殷當伐，固已灼知於未佔之先，豈非託諸佔以一人心，而成天下之亹亹乎？迨箕子之陳疇，則曰：「謀及乃心，謀及卿士，謀及庶人，謀及卜筮。」凡以揆諸己而當理，又以允愜於人心，或有疑焉，不能不事於佔。且人謀鬼謀，聖人固有先後，豈曰圖回未審，事欲冥行，群情之逆順不暇計，時位之當否不復恤，第冀事之必成，而一諉之佔邪？夫蓍未能自靈也，神而明之，存乎其人。使其人明不燭理，識不達時，是其心方自懵懵，豈能玩爻象之變，定吉凶之佔哉？又豈能即己之神，合物之神，以開人心之神哉？又豈能使人趨吉避凶，以慰聖人憂世作易之心哉？洪範曰：「擇建立卜筮人。」又曰：「三人佔，則從二人之言。」周官占人：「歲終則計其佔之中否。」擇其人，審於聽而嚴於課計，其謹之重之如此。自包犧作卦，歷虞、夏、商，未聞其說，至周乃班班可考。大卜掌三易，占人佔八頌八故，筮人辨九筮與相筮之時，共筮之職，無不畢具，獨惜其法不傳，猶幸從左傳、國語可見其略。大抵筮雖掌於卜史，至玩佔則間出名大夫之議論。子曰：</p><p>昔者聖人之作易也，幽贊於神明而生蓍，參天兩地而倚數，觀變於陰陽而立卦，發揮於剛柔而生爻，和順於道德而理於義，窮理盡性以至於命，則筮者性命道德之事。故上聖神其法，春官率其屬，賢者序其佔。自聖人沒，道散於九流，或者乃擅之以名家，而不統於儒，豈唯斯徒自賤其業，將並其法有賤之者矣。夫儒者命佔之要，本於聖人，其法有五：曰身、曰位、曰時，曰事，曰佔。求佔之謂身，所居之謂位，所遇之謂時，命筮之謂事，兆吉凶之謂佔。故善佔者既得卦矣，必先察其人之素履，與居位之當否，遭時之險夷，又考所筮之邪正，以定佔之吉凶。姑以衛孔成子所筮論之，孟縶與元皆嬖人婤姶之子，則身也。孟長元次，則位也。襄公死，社稷無主，則時也。筮享衛國，則事也。筮元得屯，筮「孟」得屯之比，則佔也。夫繼體為君，將主社稷，臨祭祀，奉民人，事鬼神，從會朝，而孟不良能行，成子雖不筮可也。疑而兩筮之，皆得元亨。儻史朝以元為長，昧非人之義，而吉孟之佔，是使跛躄為君，而蓍失其所以靈矣。孔成子筮立孟，得屯之比，史朝以卦辭為佔；畢萬筮仕，亦得屯之比，辛廖兼本卦之卦兩象為佔，非卦同而佔異也。立君與仕，事之重輕已殊，孟縶、畢萬之身與位時又殊，雖使百人千人同得此卦，其佔烏乎而可同？南蒯將叛，筮得「坤黃裳元吉」，子服惠伯以為忠信之事則可，不然必敗。晉文筮有晉國，得屯之豫，史以為不吉，司空季子以命筮之辭佔之，曰：「吉孰大焉？」是知吉凶無常，佔由人事。固有卦吉占兇，卦兇佔吉，亦有同卦異佔，異卦同佔，非參稽五物，無以得蓍之情而窮其神也。是故業不精不筮，志不誠不筮，謀不正不筮，事不疑不筮，喜不筮，怒不筮，瀆不筮，不時不筮。離此八者，而後筮可言也。不然，神亦不告。若其用卦，或以內外卦為貞悔。 晉語：秦卜徒父筮遇蠱，曰：「貞，風也，悔，山也。」 或以本卦、之卦為貞悔。 晉語：公子筮有晉國，得貞屯悔豫。 或用變爻。 左傳哀九年：晉趙鞅卜救鄭，遇泰之需，曰：「若帝乙之元子歸妹，而有吉祿。」 或不用變爻。 晉語：董因為公子筮，得泰之八：「是謂天地泰，亨，小往大來。」 或用本卦，不用之卦。 左傳昭十二年：南蒯將叛，筮遇坤之比，曰：「黃裳元吉。」 或用之卦，不用本卦。 左傳襄九年：穆姜筮往東宮，得艮之八，曰：「隨，元、亨利、貞。」 或本卦、之卦並用。 左傳昭五年：穆子之生，莊叔筮之，遇明夷也之謙，曰：「明夷之謙，明而未融。離，火也。艮，山。」 或用二卦之下。 左傳閔元年：畢萬筮仕，遇屯之比，曰：「震為土，母覆之。」 或用二卦之上。 左傳僖十五年：晉筮嫁伯姬，遇歸妹之睽，曰：「震之離，亦離之震。」 其取象，或以八象， 左傳僖二十五年，晉卜偃筮納王，遇大有之睽，曰：「天為澤。」 或以互體， 左傳莊二十二年，陳侯筮，遇觀之否，曰：「風為天，於土上，山也。山取二三四互艮體。」 其斷吉凶，或以卦辭， 左傳昭七年，衛孔成子筮遇屯，又遇屯之比，亦曰：「元亨。」 或以爻辭， 左傳襄二十五年，崔武子筮取棠姜，遇困之大過，曰：「困於石，據於蒺藜，入於其宮，不見其妻，兇。」 或用卦名， 左傳宣六年，王子伯廖謂鄭公子曼滿無德而貪。其在周易豐之離，貪有豐義，無德有離義。 或用當時佔書， 左傳昭十二年，子服惠伯釋黃裳，元吉。黃，中之色也；裳，下之飾也。元，善之長也。 要在玩佔者忠信正直，達權識變，而後其佔不忒。若子太叔舉復之頤，佔楚子之將死。 左傳襄二十八年， 王子伯廖舉豐之離，佔曼滿之見殺。是專以人事逆其吉凶，有不待筮而知者，此春秋諸臣猶能得聖人觀象玩辭之遺意。自時厥後，性命道德之學不傳，乃盡棄人事，雖悖禮越義者，一切求吉凶於筮，而佔法遂變。至於納甲、五行、時日、六獸之類，蠭蝟而起。焦延壽作易林，以三百八十四爻之辭不能週四千九十六變之吉凶，故外易而別為之辭，乂雜以納甲飛伏之說，是舍人事義理而專於佔者也。至火珠林、軌革流衍析之流，遂陷溺於術，其別為相人、相地、壬遁、星命百家，自謂能定吉凶於人事未動之前。籲！視性命道德之學為何事邪？子曰：「吉凶悔吝，生乎動者也。」方其未動，吉凶未兆，使慮善以動，則兇者可吉；謀用不臧，則吉者亦兇。今雲定吉凶於人事未動之前，則中才無所勸，凶德無所警，此「我生不有命在天」，所以為鑑於萬世。卦變釋第十</p><p>前所言變卦、卦變不同。蓋卦變者，卦自為變；變卦者，變因乎蓍。懼學者混而為一，失聖人命辭之旨，故析圖之。太極兩儀，□□四象，□□</p><p>八卦，☰乾、☳「震」、☵坎、☶艮、☷坤、☴「巽」、☲「離」、☱兌。「儀」者，一奇一耦之名。「儀」，表也。有形之始，姑以此表陰陽也。「象」者，二奇二耦之名。自一奇一耦衍而成象。「象」，像也，漸著於儀，未適於變也。「卦」者，三奇三耦之名。益著於象，以交以重，而萬變備矣。曰「儀」，曰「象」，曰「卦」，由微至著。此說卦之義，與先天不同。說卦：「乾、坤生六子」，先天八卦同成</p><p>八卦，互乘變為六十四卦。</p><p>此無先後。今以說卦之序圖之，仍卦附，以釋卦變之辭：䷀ 乾下乾上</p><p>乾䷊</p><p>乾下坤上 泰。內健而外順。䷡</p><p>乾下震上 大壯。剛以動。䷈</p><p>乾下巽上 小畜，健而巽。䷄</p><p>乾下坎上 需，剛健而不陷。䷍</p><p>乾下離上 大有，剛健而文明。䷙</p><p>乾下艮上 大畜，健而止。䷪</p><p>乾下兌上 夬，健而說。䷁ 坤下坤上</p><p>坤䷋</p><p>坤下乾上 否，內柔而外剛。䷏</p><p>坤下震上 豫。順以動。䷓</p><p>坤下巽上 觀。「順而巽」，䷇</p><p>坤下坎上 比。「下順從也」。䷢</p><p>坤下離上 晉。「順而麗乎大明」，䷖</p><p>坤下艮上 剝。「順而止之」，䷬</p><p>坤下兌上 萃。「順以說」，䷲ 震下震上 震。「震來虩虩」，䷘</p><p>震下乾上 無妄。「動而健」，䷗</p><p>震下坤上 復。「剛反動而以順行」，䷩</p><p>震下巽上 益，損上益，下。「動而巽」，䷂</p><p>震下坎上 屯。「動乎險中」，䷔</p><p>震下離上 噬嗑。「動而明」，䷚ 震下艮上 頤，䷐</p><p>震下兌上 隨。「動而說」，䷸</p><p>巽下巽上 巽。「重巽以申命」，䷫</p><p>巽下乾上 姤。「柔遇剛也」。䷭</p><p>巽下坤上 升。「巽而順」，䷟</p><p>巽下震上 恆。「巽而動」，䷯</p><p>巽下坎上 井。「巽乎水而上水」，䷱</p><p>巽下離上 鼎。「以木巽火」，䷑</p><p>巽下艮上 蠱。「巽而止」，䷛</p><p>巽下兌上 大過。「巽而說」，䷜</p><p>坎下坎上 坎。「重險也」，䷅</p><p>坎下乾上 訟。「險而健」，䷆</p><p>坎下坤上 師。「行險而順」，䷧</p><p>坎下震上 解。「險以動」，䷺</p><p>坎下巽上 渙。「利涉大川」，乘木有功也。䷿ 坎下離上 未濟，䷃</p><p>坎下艮上 蒙。「險而止」，䷮</p><p>坎下兌上 困。「險以說」，䷝</p><p>離下離上 離。「重明以麗乎正」，䷌</p><p>離下乾上 同人。「文明以健」，䷣</p><p>離下坤上 明夷，內文明而外柔順。䷶</p><p>離下震上 豐。「明以動」。䷤</p><p>離下巽上 家人，「女正位乎內，男正位乎外」。䷾ 離下坎上 既濟，䷕</p><p>離下艮上 賁。「文明以止」。䷰</p><p>離下兌上 革。「文明以說」，䷳</p><p>艮下艮上 艮。「艮其止」，䷠</p><p>艮下乾上 遁。「浸而長也。」䷎</p><p>艮下坤上 謙。天道下濟而光明，地道卑而上行。䷽</p><p>艮下震上 小過。「有飛鳥之象焉」。䷴</p><p>艮下巽上 漸。「止而巽」。䷦</p><p>艮下坎上 蹇。「見險而能止」，䷷</p><p>艮下離上 旅。「止而麗乎明」，䷞</p><p>艮下兌上 鹹。「止而說」。䷹</p><p>兌下兌上 兌。「說以先民，說以犯難」。䷉</p><p>兌下乾上 履。說而應乎乾。䷒</p><p>兌下坤上 臨。「說而順」。䷵</p><p>兌下震上 歸妹。「說以動」，䷼</p><p>兌下巽上 中孚，「說而巽」。䷻</p><p>兌下坎上 節。「說以行險」。䷥</p><p>兌下離上 睽。「說而麗乎明」。䷨</p><p>兌下艮上 損。損下益上爻變釋第十䷀六陽䷁六陰，</p><p>六十四卦一陰陽也。乾純陽，坤純陰，故為易之門。䷗一陽䷒二陽䷊三陽，䷫一陰䷠二陰䷋三陰，</p><p>六爻，兩卦之重也。上卦乾坤之體；下卦乾坤之變，故此六卦為變之始。陰陽各從其類，互變各循其序。此重卦後之變，聖人取以系釋彖之辭。今各釋其下，與蓍變先天不同。䷆</p><p>師：剛中而應。 初二互變。 ䷎</p><p>謙：「謙尊而光」。 初三互變。 ䷏</p><p>豫，「剛應而志行」。 初四互變。 ䷇</p><p>比：以剛中也。 初五互變。 ䷖</p><p>剝：柔變剛也。 初上互變。 右一陽爻卦䷣</p><p>明夷，「明入地中」。 二三互變。 ䷲</p><p>震：「出可以守宗廟社稷」。 二四互變。 ䷂</p><p>屯：「剛柔始交而難生」。 二五互變。 ䷚</p><p>頤：「自求口實」。 二上互變。</p><p>右二陽爻卦九二爻變䷭</p><p>升：「柔以時升」。 初三互變。 ䷧</p><p>解：「其來複吉，乃得中也」。 初四互變。 ䷜</p><p>坎：「乃以剛中也。」 初五互變。 ䷃</p><p>蒙：「山下有險。」 初上互變。 右二陽爻卦初九爻變䷽</p><p>小過，「柔得中，剛失位而不中。」 二四互變。初三互變。 ䷬</p><p>萃：「剛中而應。」 二五互變。初四互變。 ䷓</p><p>觀：「中正以觀天下，下觀而化。」 二上互變。初五互變。</p><p>右二陽爻卦九二、初九、比爻同變。䷦</p><p>蹇：「往得中也。」 二五互變。初三互變。 ䷢</p><p>晉：「明出地上，柔進而上行。」 二上互變。初四互變。</p><p>右二陽爻卦，九二初九間一爻同變。䷳</p><p>艮：「上下敵應。」 二上互變。初三互變。</p><p>右二陽爻卦，九二初九間兩爻同變。䷵</p><p>歸妹：「徵兇，位不當也。」 三四互變。 ䷻</p><p>節：「剛柔分而剛得中。」 三五互變。 ䷨</p><p>損：「損下益上。」 三土互變。</p><p>右三陽爻卦，九三爻變。䷶</p><p>豐：「日中則昃。」 二四互變。 ䷾</p><p>既濟，「剛柔正而位當，柔得中也。」 二五互變。 ䷕</p><p>賁，「柔來而文剛」；分剛上而文柔。 二上互變。</p><p>右三陽爻卦，九二爻變。䷟</p><p>恆，剛上而柔下。 初四互變。 ䷑</p><p>井：「乃以剛中也。」 初五互變。 ䷑</p><p>蠱：「剛上而柔下。」 初三互變。</p><p>右三陽爻卦，初九爻變。䷌</p><p>同人，「柔得位得中。」 初二互變。 ䷉</p><p>履，「柔履剛也。」 初三互變。 ䷈</p><p>小畜，「柔得位。」 初四互變。 ䷍</p><p>大有，「柔得尊位。」 初五互變。 ䷪</p><p>夬，「柔乘五剛也」。 初上互變。 右一陰爻卦䷅</p><p>訟，「剛來而得中也」。 二三互變。 ䷸</p><p>巽：「剛巽乎中正」。 二四互變。 ䷱</p><p>鼎，「柔進而上行」。 二五互變。 ䷛</p><p>大過，「剛過而中」。 二上互變。 右二陰爻卦，六二爻變。䷘</p><p>無妄：「剛自外來，而為主於內」。 初三互變。 ䷤</p><p>家人：「女正位乎內，男正位乎外。」 初四互變。 ䷝</p><p>離：「柔麗乎中正」。 初五互變。 ䷰</p><p>革：「革而當。」 初上互變。</p><p>右二陰爻卦，初六爻變。䷼</p><p>中孚：「柔在內而剛得中。」 二四互變，初三互變。 ䷙</p><p>大畜：「剛上而尚賢」。 二五互變，初四互變。 ䷡</p><p>大壯：「大者壯也。」 二上互變，初五互變。</p><p>右二陰爻卦，六二、初六比爻同變。䷥</p><p>睽：「柔進而上行，得中而應乎剛。」 二五互變，初三互變。 ䷄需：「險在前也。」 二上互變，初四互變。</p><p>右二陰爻卦，六二、初六間一爻同變。䷹</p><p>兌：「剛中而柔外。」 二上互變，初三互變。</p><p>右二陰爻卦，六二、初六間兩爻同變。䷴</p><p>漸：「進得位」。 三四互變。 ䷷</p><p>旅：柔得中乎外。 三五互變。 ䷞</p><p>鹹：「柔上而剛下」。 三上互變。</p><p>右三陰爻卦，六三爻變。䷺</p><p>渙：「剛來而不窮」。 二四互變。 ䷿</p><p>未濟：「柔得中也，剛柔應也。」 三五互變。 ䷮</p><p>困：「以剛中也」。 二上互變。</p><p>右三陰爻卦，六二爻變。䷩</p><p>益，「損上益下」。 初四互變。 ䷔</p><p>噬嗑，「剛柔分」，「柔得中而上行」。 初五互變。 ䷐</p><p>隨，剛來而下柔。 初上互變。</p><p>右三陰爻卦，初六爻變。得失釋第十二</p><p>不變不動，得失何有？得失生乎動者也。釋彖之辭，凡言得失者，皆因乎變動，不者言當否。固有變動而不言得失者，無不動而言得失者，今各隨爻變釋之。䷧</p><p>解，其來複吉，乃得中也。䷽</p><p>小過，柔得中，剛失位而不中。䷦蹇，往得中也。䷻</p><p>節，剛柔分而剛得中。䷾既濟，柔得中也。䷌同人，柔得位得中。䷈小畜，柔得位。䷍大有，柔得尊位。䷅訟，剛來而得中也。䷱鼎，得中而應乎剛。䷼</p><p>中孚，柔在內而剛得中。䷥睽，得中而應乎剛。䷴</p><p>漸，進得位其位，剛得中也。䷷旅，柔得中乎外。䷺渙，柔得位乎外。䷿未濟，柔得中也。䷔</p><p>噬嗑，柔得中而上行。八卦釋第十三</p><p>乾為天，為陽，為天德，為元，為資始，為剛健，為純粹精，為首，為龍，為六龍，為群龍，為玄。</p><p>坤為地，為陰，為元，為資生、為厚載、為柔順、為含弘光大、為牝馬、為黃。</p><p>震為雷、為動、為驚、為振、為頻。巽為風、為木、為巽</p><p>坎為水、為雨、為雲、為泉、為險、為陷。離為火、為電、為明、為大明、為文明、為牝牛、為麗、為雉。艮為山、為止。兌為澤、為說。六爻釋第十四</p><p>初為初、為始、為出、為出門、為童。於下為下、為地、為泥、為幹、為床、為潛、為隱、為藏、為履、為藉、為浚、為拔、為入、為民、為足、為趾、為臀、為屨校、為車、為輪、為徒。於外為郊、為門、為門庭、為侯、為拇。於經卦為內、為戶庭。於前為前趾。於後為曳、為尾。</p><p>二為地上、為田、為耕穫菑畬、為井谷、為磐、為見、為中、為時中、為輿、為輪、為輹、為床辨、為門庭、為鼎腹、為機、為幽人、為腓。於陽「為大人、為長子、為子、為大車。於陰為女、為中饋、為黃牛、為正。比五為內，同五為宗。姤五為巷，三為人、為公、為夤、為心、為股、為乘、為輻。於陽為重剛，於陰為弟子。於經卦為上、為外、為終、為陸、為高陵、為上下卦之際。四為人之上，為卦之革，為墉、為木、為丘、為輹、為躍。於陽為金車、為鼫鼠」。於乾為重剛，於復為中。三四為進退往復，來之</p><p>五為天、為陵、為階、為正、「為中」、「為輔車」、為脢、「為鼎耳」、「為黃金」、「為大君」、「為王公」、「為帝位」、「為天位」、「為王居」、「為尊位」、「為大中」；於陰為女君、為帝子、為帝女、為宮人。應二為宗上、為天、為天衢、為上、為亢、為高墉、為城、為巢、為鉉、為幕、為角、為頂、為首、為何校、為耳、為輔頰舌、為公、為侯、為高尚。於終為終、為窮、為盈、為極、為冥、為迷。於後為後，於外為郊、為野、為出、為征伐。陰陽釋第十五</p><p>陽為九，為天、為日、為雷、為大人、為祖、為父、為考、為夫、為夫子、為長子、為子、為男、為老夫、為士夫、為丈夫、為丈人、為君子、為大師、為龍、為馬、為虎、為羝羊、為金、為金車、為金鉉、為黃矢、為剛、為顯、為富、為實、為貴、為大、為動、為東北、為右陰、為六、為地、為月、為雷、為夕、為霜、為冰、為雲、為妣、為王母、為母、為妻、為婦、為女妻、為老婦、為女子、為童、為弟子、為小子、為娣、為妹、為臣妾、為小人、為牝馬、為牛、為童牛、為牝牛，為豹、為鹿、為豕、為羸豕、為魚、為鬼、為林、為叢棘、為穴、為淵、為幽谷、為血、為囊、為冥、為不富、為柔、為含、為賤、為小、為靜、為西南、為左、為八月。</p><p>陰陽和為雨合、為應、為婚遇、為夫妻。 比爻同， 否則為寇，為敵，非應為它。剛柔節為玉鉉。太極名義釋第十六</p><p>今古有極乎？曰：有。物變有極乎？曰：有。然則惡乎極？曰：極於道。夫浩乎萬類，紛如臧否，使凡進修酬酢，鹹適厥宜，一揆諸道而極。雖天地高厚，鬼神幽變，悉不逃是。然則道者，事之極也。道為事極，故即極而為之名。 此一節明極之所以名。 建於上曰「皇極」；作於下曰「民極」，體之三才曰三極。 此一節明極隨寓而異名。 溯而上之，八卦、四象、兩儀之原曰太極。觸類引比，則太極為天地、陰陽之理，而形氣未著，是生兩儀。則天地其形，陰陽其氣。 太極之名，始於大傳，本以推兩儀、四象、八卦之原，今假以明道，故曰「觸類引比」。 天地奠其區，陰陽交其精，人物生焉。人為萬物之靈，於是父子以續，夫婦以耦，長幼以序。強弱爭而作之君，氣稟偏而輔之友。誠以為主，知以明之，勇以行之，修諸身，放諸四海，達諸古今而不悖。君極於君道，臣極於臣道，父子極於父子之道，夫婦、長幼、朋友莫不各臻其極，而人極立。人極立而天地之極立，三極立而大極之體用彰矣。 此一節明太極流行之縕。 然曰極足矣，而復雲太極，何邪？曰：物物皆具者曰「萬化之極」，其為萬化之極之極者曰「太極」，猶尊於皇帝曰「太上皇」，長於諸子曰「太子」。 日為眾陽之宗，故曰「太陽」；月為眾陰之宗，故曰「太陰」。他稱「太」者皆類此。 「太極」雲者，所以別於萬化之極，而萬化之極，非於太極之外他有極也。 此一節明「極」字上加「太」字之義。 或曰：周子太極圖言「無極」，殆幾老、列之論乎？曰：周子主於「道」，老氏主於「無」，禦寇主於「跡」。老氏未嘗言「太極」，而以「無」喻道。其曰「復歸於無極」，謂復歸於無而極，以「知白守黑」、「常德不忒」為未極，必欲復歸於道而後極。禦寇於上下八方有「極盡」之問，為「無無極」之對，特駕為渺茫，以肆其辯。且極已極矣，極之外何所求無？無即無矣，無之外安得更無？若然，則彼所謂「極」者，未為「極」；「無」者，未為無也。且禦寇誠疏矣，然有無非所以論道。「天地未判」，非「無」也，有太極焉。既判，而物物皆具此極。「無聲無臭」，非「有」也，而老氏以「無」喻道。故知禦寇之言與老氏殊，老氏之言與周子殊。 此一節明老、列「無極」之義。 或曰：周子加「無極」於太極之上，而莊周雲「道在太極之先」，得無同乎？曰：不同。莊周襲吾夫子「太極」之名，而不明其體。其曰在太極之先而不為高，在六極之下而不為深，曰高與深皆指形跡，遂認太極為六極之儔。彼蓋習其師「有物混成，先天地生」之說，不知老氏曰「無」，曰「惚恍」，曰「先天地生」，皆道之別名，亦大傳所謂「太極」也。太極與道安有先後？今雲「在太極之先」，是太極與天地皆有形之物，其失遠甚。 此一節明莊周太極之義。 若周子云「太極本無極」，未嘗岐之而為二，亦未嘗以太極為有形，而以無極加太極之上，安得與莊周同乎？學者必洞究三氏之所以失，然後知周子之所以得。 大抵讀書當通一章上下文，以繹其義。今通三氏上下文，則知與周子得失不同。 嗚呼！太極者，道之別名也。有名斯有義，名義得，然後識太極之真體。真體云何？生生萬化，其前莫加範圍萬化其變莫外。象數體用圖釋第十七</p><p>盈天地之間，可見皆象，可計皆數，雖殊類異形，千變萬化，曾莫越象數之外。曰象曰數，有體有用，為圖凡四。乾上坤下，為象之體，不必曰包犧。先天離南坎北，為象之用，不必曰文王。後天一六二七，為數之體，不必曰河圖。一九三七，為數之用，不必曰洛書。各疏其原於左。象體 天地定位以至水火不相射。 象用 「帝出乎震」以至「成言乎艮」。</p><p>數體 天一以至地十。 數用 履一以至戴九。 乾上坤下，天地之體巽離兌由乾體而索，本乎天者，親上，故附乾；震坎艮由坤體而索本乎地者，親下，故附坤。此象之體也。乾坤定位，六子分行，坎離自然當東西之中，而八象對立亦合自然。天地位，二氣分，分必合，合必交，乾坤交而為坎離。離之外具乾之體，中則坤致其用；坎之外具坤之體，中則乾致其用。由外觀之，乾坤之體未嘗變，其中則交矣。故天地之用莫妙於水火，雖坎離也，實乾坤也。乾坤立天地之體而其用藏，坎離具乾坤之體而其用著。因乾坤之用而圖之，坎離居中，乾坤居其旁，非退乾坤也。既交之後，下皆乾，上皆坤，布以為圖，乃見如是。震艮從乾父而聚於東北，巽兌從坤母而聚於西南，而陰陽之群以分。乾坤用交，餘卦佈列，自有出震成艮之序，此乃聖人因類辨方，隨方命辭，非私出意見以傅會其說也。體圖辨天地之體而人居中，當立以觀，故言上下。用圖合天地之用以利斯世，當偃以觀，故言方所。天地既交，數體以立，故天交於下一居之平視則北，地交於上二居之平視則南。三居東為陽，四居西為陰，五乃居中。自是六合一，七合二，八合三，九合四，十合五。一二三四五為自然之位，六七八九十為自然之合。自一至十而數體備，由是而億兆皆十而積也。體十而用九，理之自然，九可變，十不可變，今之因乘法可見也。其數一北而二南，陽三而陰二，陽左旋，陰右轉。一在北，一而三之；三在東，三而三之；九在南，九而三之；七在西，七而三之，一復其本。二在西南，二而二之；四在東南，四而二之；八在東北，八而二之；六在西北，六而二之，二復其本。陰陽數交，自然定位，不可易置其一而妙用無窮。或曰：「一北二南，今二何為在西南？」曰「是亦南也。」陽數居四方，故陰數居四維，猶坎離居中，而乾坤居其旁，此圖之形也，識者當以理觀。八數析位，因奠八方，五運於中，九位備矣。</p><p>右溯未圖之前而探其原，其體用如此。若沿已圖之後而演其流，則象體圖有八卦相錯之用，象用圖定八方之體，數體圖有陰陽合德之用，數用圖類五行之體。體以致用，用不離體，體用二名，實則一致。 子傳百家，凡合於此者，皆圖後之說，非圖前之理。 圖書釋第十八浩浩元氣，精靈具存，混淪既分，昭乎日星之在上，確乎川嶽之在下。自然之文若是，孰為之者？抑亦元氣流精，物物神奇爾。河圖、洛書，聖人則之，東序陳之，其來已久，形制不傳，其為文若數，莫可臆知，而聖人寶尚如此，是亦自然之文，非人力之所作為也。典籍灰揚，存者可考。聖人不過曰「河出圖，洛出書」，初未嘗明著其文。漢儒乃指為畫卦敘疇之原。劉歆謂：「洪範自五行至六極凡六十五字，皆洛書本文，是洛書不為數也。揚雄明一六、二七之數，鑿度述一九、三七之敘，不聞有圖、書之名，是數不為圖、書也。獨孔安國謂神龜負文於背，有數至九，則以洛書為數矣。」夫安國、歆皆漢碩儒，歆又專佐符命，宜見秘文，其說之異同乃如此，豈圖、書已亡於漢，二子姑以意定言邪？ 鄭康成謂河圖九篇，洛書六篇，又別有三十篇，後漢曹充、李邰、公沙穆之徒皆習之，其文則劉昭注天文志足以槩見。今案此乃圖緯之書， 後之學者緬企圖、書之名，習安國之說，而數不可見，遂以揚雄鑿度之數強名曰圖、書，而聖人之所寶，中古之所不傳，始斷斷乎為數矣。雄之數十，凡五位，止於五十，後人衍為五十五，目之曰河圖。鑿度之數九，其位亦九，後人因太乙遊宮之次，目之曰洛書。至劉牧互易其名，朱子雖復其舊，迨今學者所主猶未一。況陳希夷有未合已合之分，邵康節有圓數方文之辨。若畫卦、敘疇等論，由漢以來，紛紜誕異，不可勝載，奈之何哉！且聖人儕圖、書於神物變化垂象之列，箕子但云「天錫九疇」，未嘗指包犧則圖而畫卦，大禹法書而敘疇也。聖經所載，炳然甚明，何後人不之信，而遽祖漢儒邪？為則圖畫卦之說者，以九六七八配陰陽老少，謂聖人畫卦蓋本諸此。不知九六七八為揲蓍策數，乃先有卦而後揲蓍，非先得數而後畫卦。況包犧仰觀俯察，近取遠取，不過天地人物之象乎？為法書敘疇之說者，沿洪範「天錫」之語，以為龜負數而出，禹因第為九類。使龜文不出，則宇宙間無此九類邪？況天錫勇智，天錫純嘏，不知天命何物負之以錫諸人也？嗚呼！河圖、洛書，古必有是，儻形制湮泯，正可闕疑，何至依緣髣像，以一時臆見而斷千古之疑邪？若夫圖或為書，書或為圖，其無所取證於聖人則均也。雖然，此二數者，如不名之為圖書，而直論其數，則有不可廢者。一對二，三對四，而五居中，六七合一二，八九合三四，而十合五，奇耦胥對，陰陽有合，而數之體以立。聖人所謂「陰陽合德而剛柔有體」者，此其類也。體立矣，不變則數不行，故陽以三左行，陰以二右行。三其一為三而居東，三其三為九而居南，三其九為二十七，而七居西，三其二十七為八十一，而一復居北。等而上之，至於億兆，其餘數之位皆然。二其二為四而居東南，二其四為八而居東北，二其八為十六而六居西北，二其十六為三十二，而二復居西南。上而億兆亦然。 八方之名，姑藉以立辭。 八位既列，五仍居中，而數之用以通。聖人所謂「參互以變，錯綜其數」者，此其類也。夫數雖有體用，而貫於體用之間者，一三五也。一為數之始，五為數之中，三為奇耦之合，故體用之圖雖不同，而一三五之位不易也。或曰：「數一而已，何有體用之殊？」籲，數豈有二本哉？曰體曰用，鹹肇乎一。對布之以立體，錯布之以通用，顧人所布如何爾。凡天下之數，雖有萬不同，皆始於一也。或又曰：「然則易之數云何？」曰：易書有衍數，有積數。自五衍而為五十者，衍數也；自一二三四五積而為五十五者，積數也。圖、書二數皆積數之儔，不可以與於揲蓍也。故舍圖、書之名而論二數，則自有妙理；強二數以圖、書之名，則於經無據。況欲牽合九六七八以為四象，傳會五行生成以配八卦，而謂之作易之原，可乎？易雅。</p>',174)])])}const f=e(r,[["render",i]]);export{m as __pageData,f as default};
